<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Factories\HasFactory;
class Product extends Model { use HasFactory; protected $fillable=['vendor_id','category_id','name','slug','description','sku','price','compare_at_price','is_featured','is_active','is_approved','approved_at','weight_grams']; protected function casts():array{return ['price'=>'decimal:2','compare_at_price'=>'decimal:2','is_featured'=>'boolean','is_active'=>'boolean','is_approved'=>'boolean','approved_at'=>'datetime'];} public function vendor(){return $this->belongsTo(Vendor::class);} public function category(){return $this->belongsTo(Category::class);} public function images(){return $this->hasMany(ProductImage::class);} public function inventory(){return $this->hasOne(Inventory::class);} public function reviews(){return $this->hasMany(Review::class);} public function scopeAvailable($q){return $q->where('is_active',true)->where('is_approved',true)->whereHas('inventory',fn($i)=>$i->where('quantity','>',0));} }
